BEGIN;
DO $$
DECLARE
  v_subject_id UUID;
  v_topic_id UUID;
  v_test_id BIGINT;
BEGIN
  SELECT id INTO v_subject_id FROM test_subjects WHERE name ILIKE '%cardio%' ORDER BY id LIMIT 1;
  IF v_subject_id IS NULL THEN
    INSERT INTO test_subjects (name, description) VALUES ('Cardiovascular System', 'Cardiovascular notes') RETURNING id INTO v_subject_id;
  END IF;
  SELECT id INTO v_topic_id FROM test_topics WHERE name ILIKE '%ekg%' ORDER BY (SELECT COUNT(*) FROM test_questions q WHERE q.topic_id = test_topics.id) DESC, created_at ASC LIMIT 1;
  IF v_topic_id IS NULL THEN
    INSERT INTO test_topics (subject_id, name, description, status) VALUES (v_subject_id, 'EKG', 'Electrocardiogram analysis', 'published') RETURNING id INTO v_topic_id;
  END IF;
  SELECT id INTO v_test_id FROM tests WHERE is_active = true ORDER BY id LIMIT 1;
  IF v_test_id IS NULL THEN
    INSERT INTO tests (test_name, system_category, description, is_active)
    VALUES ('Cardiovascular System - EKG (Generated)', 'Cardiovascular System', 'Auto-generated NCLEX question set', true)
    RETURNING id INTO v_test_id;
  END IF;
  DELETE FROM test_questions WHERE topic_id = v_topic_id AND category = 'EKG';
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing the cardiac conduction system with a student. Which structure briefly pauses the impulse so the atria can empty into the ventricles before the ventricles contract?', 'The nurse is reviewing the cardiac conduction system with a student. Which structure briefly pauses the impulse so the atria can empty into the ventricles before the ventricles contract?', '[{"id": "a", "text": "Purkinje fibers"}, {"id": "b", "text": "AV node"}, {"id": "c", "text": "SA node"}, {"id": "d", "text": "Bundle of His"}]'::jsonb, '["b"]', 'The AV node acts as the gatekeeper. It pauses the signal so the atria can empty their blood into the ventricles before the ventricles contract.', 'EKG', false, 1, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'A student asks which structure normally starts each heartbeat at a rate of 60-100 bpm. What is the nurse''s best response?', 'A student asks which structure normally starts each heartbeat at a rate of 60-100 bpm. What is the nurse''s best response?', '[{"id": "a", "text": "The atrioventricular (AV) node"}, {"id": "b", "text": "The Bundle of His"}, {"id": "c", "text": "The Purkinje fibers"}, {"id": "d", "text": "The sinoatrial (SA) node"}]'::jsonb, '["d"]', 'The SA node is the pacemaker of the heart. It fires at 60-100 bpm and sends the wave through the atria.', 'EKG', false, 2, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'After the impulse leaves the AV node, which pathway does it follow to make the ventricles contract?', 'After the impulse leaves the AV node, which pathway does it follow to make the ventricles contract?', '[{"id": "a", "text": "Purkinje fibers, then the bundle branches, then the Bundle of His"}, {"id": "b", "text": "Bundle of His, then the left and right bundle branches, then the Purkinje fibers"}, {"id": "c", "text": "Left and right bundle branches, then the SA node, then the Purkinje fibers"}, {"id": "d", "text": "Bundle of His, then the SA node, then the bundle branches"}]'::jsonb, '["b"]', 'The signal travels from the Bundle of His to the left and right bundle branches and then the Purkinje fibers, and the ventricles contract.', 'EKG', false, 3, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which waveform on the ECG strip represents atrial depolarization?', 'Which waveform on the ECG strip represents atrial depolarization?', '[{"id": "a", "text": "T wave"}, {"id": "b", "text": "QRS complex"}, {"id": "c", "text": "U wave"}, {"id": "d", "text": "P wave"}]'::jsonb, '["d"]', 'The P wave represents atrial depolarization.', 'EKG', false, 4, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is identifying ventricular repolarization on a rhythm strip. Which waveform represents this event?', 'The nurse is identifying ventricular repolarization on a rhythm strip. Which waveform represents this event?', '[{"id": "a", "text": "PR segment"}, {"id": "b", "text": "T wave"}, {"id": "c", "text": "P wave"}, {"id": "d", "text": "QRS complex"}]'::jsonb, '["b"]', 'The T wave represents ventricular repolarization. The QRS complex represents ventricular depolarization.', 'EKG', false, 5, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'A client''s strip shows a prominent U wave. Which electrolyte imbalance should the nurse suspect?', 'A client''s strip shows a prominent U wave. Which electrolyte imbalance should the nurse suspect?', '[{"id": "a", "text": "Hypernatremia"}, {"id": "b", "text": "Hypermagnesemia"}, {"id": "c", "text": "Hypokalemia"}, {"id": "d", "text": "Hyperkalemia"}]'::jsonb, '["c"]', 'A U wave is not always present. When it is prominent it may indicate hypokalemia.', 'EKG', false, 6, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which PR interval is within normal limits for an adult?', 'Which PR interval is within normal limits for an adult?', '[{"id": "a", "text": "0.16 sec"}, {"id": "b", "text": "0.32 sec"}, {"id": "c", "text": "0.08 sec"}, {"id": "d", "text": "0.24 sec"}]'::jsonb, '["a"]', 'A normal PR interval is 0.12-0.20 sec (3-5 small boxes). Values above 0.20 sec are prolonged.', 'EKG', false, 7, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'A client''s QRS complex measures 0.14 sec. How should the nurse interpret this finding?', 'A client''s QRS complex measures 0.14 sec. How should the nurse interpret this finding?', '[{"id": "a", "text": "The QRS is normal if the PR interval is normal"}, {"id": "b", "text": "The QRS is normal because ventricular depolarization can take 0.20 sec"}, {"id": "c", "text": "The QRS is narrow, which is normal"}, {"id": "d", "text": "The QRS is wide, which is abnormal"}]'::jsonb, '["d"]', 'A normal QRS is narrow (less than 0.12 sec). A QRS wider than 0.12 sec is wide and abnormal.', 'EKG', false, 8, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'On standard ECG paper moving at 25 mm/sec, how much time does one large box represent?', 'On standard ECG paper moving at 25 mm/sec, how much time does one large box represent?', '[{"id": "a", "text": "0.04 sec"}, {"id": "b", "text": "1.00 sec"}, {"id": "c", "text": "0.10 sec"}, {"id": "d", "text": "0.20 sec"}]'::jsonb, '["d"]', 'One large box is 5 small boxes x 0.04 sec = 0.20 sec.', 'EKG', false, 9, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'A client has a regular rhythm with 4 large boxes between consecutive R waves. What is the heart rate?', 'A client has a regular rhythm with 4 large boxes between consecutive R waves. What is the heart rate?', '[{"id": "a", "text": "60 bpm"}, {"id": "b", "text": "150 bpm"}, {"id": "c", "text": "100 bpm"}, {"id": "d", "text": "75 bpm"}]'::jsonb, '["d"]', 'For a regular rhythm, heart rate = 300 divided by the large boxes between R waves, so 300 / 4 = 75 bpm.', 'EKG', false, 10, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'A client has an irregular rhythm. The nurse counts 8 QRS complexes in a 6-second strip. What is the heart rate?', 'A client has an irregular rhythm. The nurse counts 8 QRS complexes in a 6-second strip. What is the heart rate?', '[{"id": "a", "text": "160 bpm"}, {"id": "b", "text": "100 bpm"}, {"id": "c", "text": "80 bpm"}, {"id": "d", "text": "48 bpm"}]'::jsonb, '["c"]', 'For an irregular rhythm, count the QRS complexes in a 6-second strip and multiply by 10: 8 x 10 = 80 bpm.', 'EKG', false, 11, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which method should the nurse use to calculate the heart rate of an irregular rhythm?', 'Which method should the nurse use to calculate the heart rate of an irregular rhythm?', '[{"id": "a", "text": "Count the QRS complexes in a 6-second strip and multiply by 10"}, {"id": "b", "text": "Count the P waves in one large box and multiply by 60"}, {"id": "c", "text": "Divide 300 by the number of large boxes between two R waves"}, {"id": "d", "text": "Match the large boxes between R waves to 300, 150, 100, 75, 60, 50"}]'::jsonb, '["a"]', 'Dividing 300 by large boxes and the 300-150-100-75-60-50 sequence only work for regular rhythms. Irregular rhythms use the QRS count x 10.', 'EKG', false, 12, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'A client with a palpable pulse has unstable SVT. Which intervention does the nurse anticipate?', 'A client with a palpable pulse has unstable SVT. Which intervention does the nurse anticipate?', '[{"id": "a", "text": "Unsynchronized defibrillation with the SYNC button off"}, {"id": "b", "text": "Synchronized cardioversion with the SYNC button on"}, {"id": "c", "text": "Chest compressions followed by epinephrine"}, {"id": "d", "text": "IV magnesium sulfate"}]'::jsonb, '["b"]', 'Cardioversion is used when the client has a pulse: low energy, SYNC ON. Unstable SVT is treated with synchronized cardioversion.', 'EKG', false, 13, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Why is the synchronizer turned on before cardioversion?', 'Why is the synchronizer turned on before cardioversion?', '[{"id": "a", "text": "The shock is delivered immediately because every second counts"}, {"id": "b", "text": "The shock is timed to the R wave so it does not land on the vulnerable T wave"}, {"id": "c", "text": "The shock is timed to the P wave so the atria reset first"}, {"id": "d", "text": "The shock is delivered at the highest energy setting"}]'::jsonb, '["b"]', 'SYNC ON makes the machine wait and fire on the R wave. A shock on the T wave could cause V-Fib.', 'EKG', false, 14, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'A client''s monitor shows wide, bizarre QRS complexes at 190/min. The client is unresponsive with no pulse. Which action should the nurse take?', 'A client''s monitor shows wide, bizarre QRS complexes at 190/min. The client is unresponsive with no pulse. Which action should the nurse take?', '[{"id": "a", "text": "Give IV adenosine and reassess"}, {"id": "b", "text": "Perform synchronized cardioversion"}, {"id": "c", "text": "Have the client bear down as if having a bowel movement"}, {"id": "d", "text": "Call a code, start CPR, and defibrillate with the SYNC button off"}]'::jsonb, '["d"]', 'Pulseless V-Tach is shockable: Code Blue, CPR, defibrillation (SYNC off), then epinephrine and amiodarone.', 'EKG', false, 15, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which rhythm is never shocked during cardiac arrest?', 'Which rhythm is never shocked during cardiac arrest?', '[{"id": "a", "text": "Pulseless ventricular tachycardia"}, {"id": "b", "text": "Ventricular fibrillation"}, {"id": "c", "text": "Unstable torsades de pointes"}, {"id": "d", "text": "Asystole"}]'::jsonb, '["d"]', 'Asystole and PEA are non-shockable rhythms. V-Fib and pulseless V-Tach are shockable.', 'EKG', false, 16, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The monitor shows a flat line. Which action should the nurse take to confirm asystole?', 'The monitor shows a flat line. Which action should the nurse take to confirm asystole?', '[{"id": "a", "text": "Check the rhythm in a second lead and assess the client for a pulse"}, {"id": "b", "text": "Give IV magnesium sulfate"}, {"id": "c", "text": "Begin synchronized cardioversion"}, {"id": "d", "text": "Prepare to defibrillate immediately"}]'::jsonb, '["a"]', 'Confirm asystole in 2 leads, then start CPR immediately and give epinephrine. Always check the pulse first.', 'EKG', false, 17, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'A client''s monitor alarms and shows an abnormal rhythm. Which action should the nurse take first?', 'A client''s monitor alarms and shows an abnormal rhythm. Which action should the nurse take first?', '[{"id": "a", "text": "Check the client''s pulse and level of consciousness"}, {"id": "b", "text": "Prepare to defibrillate"}, {"id": "c", "text": "Notify the provider"}, {"id": "d", "text": "Administer amiodarone"}]'::jsonb, '["a"]', 'The NCLEX priority rule is to always check the pulse first. Shockable rhythms are V-Fib and pulseless V-Tach.', 'EKG', false, 18, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'A client has a regular heart rate of 44 bpm with normal P waves and a normal PR interval. The client reports dizziness and looks pale. Which medication does the nurse anticipate?', 'A client has a regular heart rate of 44 bpm with normal P waves and a normal PR interval. The client reports dizziness and looks pale. Which medication does the nurse anticipate?', '[{"id": "a", "text": "Diltiazem"}, {"id": "b", "text": "Adenosine"}, {"id": "c", "text": "Atropine"}, {"id": "d", "text": "Magnesium sulfate"}]'::jsonb, '["c"]', 'Symptomatic sinus bradycardia (dizziness, pallor, fatigue) is treated with atropine.', 'EKG', false, 19, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse has given atropine to a client with symptomatic sinus bradycardia. Which assessment is the priority afterward?', 'The nurse has given atropine to a client with symptomatic sinus bradycardia. Which assessment is the priority afterward?', '[{"id": "a", "text": "Serum magnesium and QT interval"}, {"id": "b", "text": "Blood glucose and ketones"}, {"id": "c", "text": "Blood pressure and heart rate"}, {"id": "d", "text": "Urine output and daily weight"}]'::jsonb, '["c"]', 'Atropine activates the sympathetic nervous system and increases BP and HR, so both are monitored after it is given.', 'EKG', false, 20, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'A client has a heart rate of 54 bpm with a regular rhythm and normal P waves. The client is alert and has no symptoms. What action is most appropriate?', 'A client has a heart rate of 54 bpm with a regular rhythm and normal P waves. The client is alert and has no symptoms. What action is most appropriate?', '[{"id": "a", "text": "Document the rhythm and continue to monitor"}, {"id": "b", "text": "Prepare for emergency pacing"}, {"id": "c", "text": "Perform synchronized cardioversion"}, {"id": "d", "text": "Administer atropine"}]'::jsonb, '["a"]', 'Asymptomatic sinus bradycardia needs no treatment. Document and monitor.', 'EKG', false, 21, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'A client with sinus tachycardia also has COPD. Which medication class should the nurse question?', 'A client with sinus tachycardia also has COPD. Which medication class should the nurse question?', '[{"id": "a", "text": "Calcium channel blockers such as diltiazem and verapamil"}, {"id": "b", "text": "Stool softeners such as docusate"}, {"id": "c", "text": "Electrolyte replacement such as magnesium sulfate"}, {"id": "d", "text": "Anticoagulants such as warfarin"}]'::jsonb, '["a"]', 'Calcium channel blockers (diltiazem, verapamil) are not given to clients with COPD.', 'EKG', false, 22, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which finding in a client taking digoxin indicates toxicity?', 'Which finding in a client taking digoxin indicates toxicity?', '[{"id": "a", "text": "Yellow-green vision with halos around lights"}, {"id": "b", "text": "Increased appetite"}, {"id": "c", "text": "Clear vision with improved energy"}, {"id": "d", "text": "A regular pulse of 78 bpm"}]'::jsonb, '["a"]', 'Digoxin toxicity causes nausea, vomiting, loss of appetite, confusion, yellow or green vision, halos, and a slow, fast, or irregular pulse.', 'EKG', false, 23, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'A stable client has SVT at 170 bpm with a regular rhythm and a narrow QRS. Which intervention should the nurse try first?', 'A stable client has SVT at 170 bpm with a regular rhythm and a narrow QRS. Which intervention should the nurse try first?', '[{"id": "a", "text": "Prepare for synchronized cardioversion"}, {"id": "b", "text": "Administer IV amiodarone"}, {"id": "c", "text": "Teach a vagal maneuver such as bearing down"}, {"id": "d", "text": "Administer IV adenosine"}]'::jsonb, '["c"]', 'SVT is treated with a vagal maneuver first. If there is no response, adenosine IV is given. Unstable clients are cardioverted.', 'EKG', false, 24, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse instructs a client in SVT to perform a vagal maneuver. Which instruction is correct?', 'The nurse instructs a client in SVT to perform a vagal maneuver. Which instruction is correct?', '[{"id": "a", "text": "Take rapid, shallow breaths"}, {"id": "b", "text": "Lie flat and raise the arms overhead"}, {"id": "c", "text": "Bear down as if having a bowel movement"}, {"id": "d", "text": "Drink a large glass of warm water quickly"}]'::jsonb, '["c"]', 'Bearing down (Valsalva) or applying ice or cold water to the face stimulates the vagus nerve.', 'EKG', false, 25, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Cold water applied to the face during a vagal maneuver stimulates which cranial nerve?', 'Cold water applied to the face during a vagal maneuver stimulates which cranial nerve?', '[{"id": "a", "text": "Cranial nerve XII (hypoglossal)"}, {"id": "b", "text": "Cranial nerve VIII (vestibulocochlear)"}, {"id": "c", "text": "Cranial nerve X (vagus)"}, {"id": "d", "text": "Cranial nerve II (optic)"}]'::jsonb, '["c"]', 'Ice or cold water on the face stimulates the vagus nerve (CN X).', 'EKG', false, 26, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'A client with SVT does not respond to vagal maneuvers. Which medication is first-line?', 'A client with SVT does not respond to vagal maneuvers. Which medication is first-line?', '[{"id": "a", "text": "Atropine IV"}, {"id": "b", "text": "Epinephrine IV"}, {"id": "c", "text": "Magnesium sulfate IV"}, {"id": "d", "text": "Adenosine IV"}]'::jsonb, '["d"]', 'If vagal maneuvers fail, adenosine IV is the first-line drug. Diltiazem or beta-blockers may follow.', 'EKG', false, 27, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'A rhythm strip shows sawtooth-shaped flutter waves between narrow QRS complexes at an atrial rate of 300 bpm. Which rhythm does the nurse identify?', 'A rhythm strip shows sawtooth-shaped flutter waves between narrow QRS complexes at an atrial rate of 300 bpm. Which rhythm does the nurse identify?', '[{"id": "a", "text": "Atrial flutter"}, {"id": "b", "text": "Ventricular tachycardia"}, {"id": "c", "text": "Supraventricular tachycardia"}, {"id": "d", "text": "Atrial fibrillation"}]'::jsonb, '["a"]', 'Atrial flutter has an atrial rate of 250-350 bpm with sawtooth F waves and narrow QRS complexes.', 'EKG', false, 28, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which complication is the nurse most concerned about in a client with atrial flutter?', 'Which complication is the nurse most concerned about in a client with atrial flutter?', '[{"id": "a", "text": "Cardiac tamponade"}, {"id": "b", "text": "Torsades de pointes"}, {"id": "c", "text": "Blood clot formation leading to stroke"}, {"id": "d", "text": "Sudden asystole with no electrical activity"}]'::jsonb, '["c"]', 'Atrial flutter carries a risk of blood clot formation and stroke, so anticoagulants are used.', 'EKG', false, 29, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which finding on the rhythm strip is characteristic of atrial fibrillation?', 'Which finding on the rhythm strip is characteristic of atrial fibrillation?', '[{"id": "a", "text": "An irregular rhythm with a wavy baseline and no distinct P waves"}, {"id": "b", "text": "A regular rhythm with sawtooth flutter waves"}, {"id": "c", "text": "A regular rhythm with a prolonged PR interval"}, {"id": "d", "text": "A wide, bizarre QRS with no P waves"}]'::jsonb, '["a"]', 'Atrial fibrillation is irregular with a wavy, chaotic baseline, no distinct P waves, and a narrow QRS.', 'EKG', false, 30, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'A client with new-onset atrial fibrillation lasting longer than 48 hours is scheduled for cardioversion. What does the nurse anticipate?', 'A client with new-onset atrial fibrillation lasting longer than 48 hours is scheduled for cardioversion. What does the nurse anticipate?', '[{"id": "a", "text": "Immediate cardioversion without anticoagulation"}, {"id": "b", "text": "IV atropine before the procedure"}, {"id": "c", "text": "Anticoagulation before the cardioversion"}, {"id": "d", "text": "Withholding anticoagulants to prevent bleeding"}]'::jsonb, '["c"]', 'Because of the stroke risk, a client in A-fib longer than 48 hours is anticoagulated before cardioversion.', 'EKG', false, 31, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which medication is used for rhythm control, rather than rate control, in atrial fibrillation?', 'Which medication is used for rhythm control, rather than rate control, in atrial fibrillation?', '[{"id": "a", "text": "Amiodarone"}, {"id": "b", "text": "Metoprolol"}, {"id": "c", "text": "Diltiazem"}, {"id": "d", "text": "Digoxin"}]'::jsonb, '["a"]', 'Rate control uses beta-blockers, diltiazem, and digoxin. Rhythm control uses amiodarone or cardioversion.', 'EKG', false, 32, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'A client in ventricular tachycardia has a palpable pulse and is hemodynamically stable. Which treatment does the nurse anticipate?', 'A client in ventricular tachycardia has a palpable pulse and is hemodynamically stable. Which treatment does the nurse anticipate?', '[{"id": "a", "text": "Atropine followed by transcutaneous pacing"}, {"id": "b", "text": "Defibrillation and chest compressions"}, {"id": "c", "text": "IV adenosine followed by vagal maneuvers"}, {"id": "d", "text": "Synchronized cardioversion and antiarrhythmics such as amiodarone or lidocaine"}]'::jsonb, '["d"]', 'V-Tach with a pulse is treated with synchronized cardioversion and medications such as amiodarone or lidocaine.', 'EKG', false, 33, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which sequence of treatment is correct for a client in ventricular fibrillation?', 'Which sequence of treatment is correct for a client in ventricular fibrillation?', '[{"id": "a", "text": "CPR, unsynchronized defibrillation, epinephrine, then amiodarone"}, {"id": "b", "text": "Anticoagulation, beta-blocker, then synchronized cardioversion"}, {"id": "c", "text": "Atropine, transcutaneous pacing, then dopamine"}, {"id": "d", "text": "Vagal maneuver, adenosine, then synchronized cardioversion"}]'::jsonb, '["a"]', 'V-Fib is an emergency: Code Blue, CPR, defibrillation (unsynchronized), epinephrine, then amiodarone.', 'EKG', false, 34, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which description matches ventricular fibrillation on the monitor?', 'Which description matches ventricular fibrillation on the monitor?', '[{"id": "a", "text": "A flat line with no electrical activity"}, {"id": "b", "text": "Chaotic electrical activity with no identifiable QRS complexes or P waves"}, {"id": "c", "text": "Sawtooth waves with narrow QRS complexes"}, {"id": "d", "text": "Regular wide QRS complexes at 180/min without P waves"}]'::jsonb, '["b"]', 'V-Fib shows chaotic, irregular electrical activity with no QRS and no P waves, and there is no effective pulse.', 'EKG', false, 35, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which finding identifies a premature ventricular contraction (PVC) on the strip?', 'Which finding identifies a premature ventricular contraction (PVC) on the strip?', '[{"id": "a", "text": "A pacing spike followed by a QRS"}, {"id": "b", "text": "A wide, bizarre QRS with no preceding P wave, followed by a compensatory pause"}, {"id": "c", "text": "A QRS that is dropped after progressively longer PR intervals"}, {"id": "d", "text": "An early narrow QRS preceded by a P wave"}]'::jsonb, '["b"]', 'A PVC is a wide, bizarre QRS with no P wave before it, and a compensatory pause follows.', 'EKG', false, 36, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'A client on telemetry has 4 PVCs in a row. How should the nurse interpret and respond?', 'A client on telemetry has 4 PVCs in a row. How should the nurse interpret and respond?', '[{"id": "a", "text": "Prepare for emergency transcutaneous pacing"}, {"id": "b", "text": "Treat it as ventricular tachycardia, monitor closely, and check electrolytes"}, {"id": "c", "text": "Record it as an expected variation of sinus rhythm"}, {"id": "d", "text": "Administer atropine and recheck in 4 hours"}]'::jsonb, '["b"]', 'Three or more PVCs in a row are V-Tach. Monitor closely and address the cause, such as electrolytes or ischemia.', 'EKG', false, 37, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'A client taking a beta-blocker has a regular rate of 72 bpm and a PR interval of 0.26 sec. Every P wave is followed by a QRS. Which interpretation is correct?', 'A client taking a beta-blocker has a regular rate of 72 bpm and a PR interval of 0.26 sec. Every P wave is followed by a QRS. Which interpretation is correct?', '[{"id": "a", "text": "Second-degree type I block; a pacemaker is needed"}, {"id": "b", "text": "First-degree AV block; no treatment is needed"}, {"id": "c", "text": "Second-degree type II block; urgent pacing is needed"}, {"id": "d", "text": "Third-degree block; emergency pacing is needed"}]'::jsonb, '["b"]', 'A prolonged PR interval (more than 0.20 sec) with every P wave conducting is first-degree AV block, often caused by beta-blockers or aging.', 'EKG', false, 38, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'A strip shows a PR interval that progressively lengthens until one QRS complex is dropped. Which rhythm is this?', 'A strip shows a PR interval that progressively lengthens until one QRS complex is dropped. Which rhythm is this?', '[{"id": "a", "text": "Second-degree AV block type II"}, {"id": "b", "text": "First-degree AV block"}, {"id": "c", "text": "Second-degree AV block type I (Wenckebach)"}, {"id": "d", "text": "Third-degree AV block"}]'::jsonb, '["c"]', 'Progressive PR lengthening until a QRS is dropped is Wenckebach (Mobitz I).', 'EKG', false, 39, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'A client with structural heart disease has a heart rate of 40 bpm, a constant PR interval, and occasional non-conducted P waves. Which action should the nurse anticipate?', 'A client with structural heart disease has a heart rate of 40 bpm, a constant PR interval, and occasional non-conducted P waves. Which action should the nurse anticipate?', '[{"id": "a", "text": "Continuing to monitor with no treatment"}, {"id": "b", "text": "Performing synchronized cardioversion"}, {"id": "c", "text": "Administering IV adenosine"}, {"id": "d", "text": "Preparing for an urgent pacemaker"}]'::jsonb, '["d"]', 'Mobitz II has a constant PR interval with non-conducted P waves and needs an urgent pacemaker.', 'EKG', false, 40, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'A client''s strip shows P waves and QRS complexes that are completely independent of each other at a rate of 35 bpm. Which intervention does the nurse anticipate?', 'A client''s strip shows P waves and QRS complexes that are completely independent of each other at a rate of 35 bpm. Which intervention does the nurse anticipate?', '[{"id": "a", "text": "Vagal maneuver"}, {"id": "b", "text": "Emergency pacemaker placement"}, {"id": "c", "text": "Synchronized cardioversion"}, {"id": "d", "text": "IV adenosine"}]'::jsonb, '["b"]', 'Third-degree (complete) heart block has no communication between atria and ventricles and requires an emergency pacemaker.', 'EKG', false, 41, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which cause is associated with second-degree AV block type II?', 'Which cause is associated with second-degree AV block type II?', '[{"id": "a", "text": "Beta-blocker use"}, {"id": "b", "text": "Structural heart disease"}, {"id": "c", "text": "Increased vagal tone"}, {"id": "d", "text": "Normal aging"}]'::jsonb, '["b"]', 'Mobitz II is caused by structural heart disease. First-degree block is often caused by beta-blockers or aging, and Wenckebach by vagal tone or medications.', 'EKG', false, 42, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse notes small vertical lines just before each QRS complex on a regular rhythm strip. What do these represent?', 'The nurse notes small vertical lines just before each QRS complex on a regular rhythm strip. What do these represent?', '[{"id": "a", "text": "Prominent U waves"}, {"id": "b", "text": "Electrical alternans"}, {"id": "c", "text": "Pacing spikes from an artificial pacemaker"}, {"id": "d", "text": "Premature ventricular contractions"}]'::jsonb, '["c"]', 'An artificial pacemaker produces pacing spikes before P waves or QRS complexes at a regular rate.', 'EKG', false, 43, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'A client''s QRS complexes twist around the baseline at a rate of 220 bpm, and the QT interval was prolonged before onset. Which medication is first-line?', 'A client''s QRS complexes twist around the baseline at a rate of 220 bpm, and the QT interval was prolonged before onset. Which medication is first-line?', '[{"id": "a", "text": "IV atropine"}, {"id": "b", "text": "IV adenosine"}, {"id": "c", "text": "IV magnesium sulfate"}, {"id": "d", "text": "Oral digoxin"}]'::jsonb, '["c"]', 'This is torsades de pointes. IV magnesium sulfate is first-line, with defibrillation if the client is unstable.', 'EKG', false, 44, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which electrolyte imbalance is associated with torsades de pointes?', 'Which electrolyte imbalance is associated with torsades de pointes?', '[{"id": "a", "text": "Hypomagnesemia"}, {"id": "b", "text": "Hypermagnesemia"}, {"id": "c", "text": "Hypernatremia"}, {"id": "d", "text": "Hypercalcemia"}]'::jsonb, '["a"]', 'Torsades de pointes is associated with hypomagnesemia and QT-prolonging drugs.', 'EKG', false, 45, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which EKG finding is considered pathognomonic for cardiac tamponade?', 'Which EKG finding is considered pathognomonic for cardiac tamponade?', '[{"id": "a", "text": "Sawtooth flutter waves"}, {"id": "b", "text": "Prominent U waves"}, {"id": "c", "text": "Electrical alternans"}, {"id": "d", "text": "Pacing spikes"}]'::jsonb, '["c"]', 'Electrical alternans, a beat-to-beat change in QRS amplitude, is pathognomonic for tamponade.', 'EKG', false, 46, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing EKG findings in a client with cardiac tamponade. Why is the QRS low voltage?', 'The nurse is reviewing EKG findings in a client with cardiac tamponade. Why is the QRS low voltage?', '[{"id": "a", "text": "Hypokalemia lowers the QRS amplitude"}, {"id": "b", "text": "The atria depolarize without the AV node"}, {"id": "c", "text": "The ventricles depolarize more slowly than normal"}, {"id": "d", "text": "Fluid surrounding the heart dampens the electrical signal"}]'::jsonb, '["d"]', 'Fluid around the heart dampens the signal and produces low-voltage QRS complexes.', 'EKG', false, 47, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'A client has a prolonged QT interval on the strip. For which rhythm is the client at risk?', 'A client has a prolonged QT interval on the strip. For which rhythm is the client at risk?', '[{"id": "a", "text": "Sinus bradycardia"}, {"id": "b", "text": "Torsades de pointes"}, {"id": "c", "text": "Atrial flutter"}, {"id": "d", "text": "First-degree AV block"}]'::jsonb, '["b"]', 'A prolonged QT interval (normal 0.36-0.44 sec) is a risk for torsades de pointes.', 'EKG', false, 48, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'On an ECG, a wave of depolarization traveling toward a lead produces which deflection?', 'On an ECG, a wave of depolarization traveling toward a lead produces which deflection?', '[{"id": "a", "text": "A pacing spike"}, {"id": "b", "text": "A downward deflection"}, {"id": "c", "text": "A flat line"}, {"id": "d", "text": "An upward deflection"}]'::jsonb, '["d"]', 'Depolarization toward a lead causes a bump up. Depolarization away from the lead causes a dip down.', 'EKG', false, 49, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which description matches normal sinus rhythm?', 'Which description matches normal sinus rhythm?', '[{"id": "a", "text": "Regular rhythm at 100-150 bpm with a hidden P wave"}, {"id": "b", "text": "Regular rhythm at 60-100 bpm with a P wave before each narrow QRS and a PR interval of 0.12-0.20 sec"}, {"id": "c", "text": "Irregular rhythm with no distinct P waves and a wavy baseline"}, {"id": "d", "text": "A rate of 30-40 bpm with P waves unrelated to the QRS"}]'::jsonb, '["b"]', 'Normal sinus rhythm is regular at 60-100 bpm with consistent P waves before narrow QRS complexes and needs no treatment.', 'EKG', false, 50, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which structures are part of the cardiac conduction pathway? (Select all that apply)', 'Which structures are part of the cardiac conduction pathway? (Select all that apply)', '[{"id": "a", "text": "Chordae tendineae"}, {"id": "b", "text": "SA node"}, {"id": "c", "text": "Purkinje fibers"}, {"id": "d", "text": "AV node"}, {"id": "e", "text": "Coronary sinus"}]'::jsonb, '["b", "c", "d"]', 'The impulse travels from the SA node to the AV node, the Bundle of His, the bundle branches, and the Purkinje fibers.', 'EKG', true, 51, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which findings are consistent with sinus bradycardia? (Select all that apply)', 'Which findings are consistent with sinus bradycardia? (Select all that apply)', '[{"id": "a", "text": "Wide, bizarre QRS complexes"}, {"id": "b", "text": "Sawtooth flutter waves"}, {"id": "c", "text": "Heart rate below 60 bpm"}, {"id": "d", "text": "Regular rhythm"}, {"id": "e", "text": "Normal P waves and PR interval"}]'::jsonb, '["c", "d", "e"]', 'Sinus bradycardia is a regular rhythm below 60 bpm that starts in the SA node with normal P waves and a normal PR interval.', 'EKG', true, 52, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'A client has symptomatic sinus bradycardia. Which signs does the nurse expect? (Select all that apply)', 'A client has symptomatic sinus bradycardia. Which signs does the nurse expect? (Select all that apply)', '[{"id": "a", "text": "Yellow-green vision"}, {"id": "b", "text": "Bounding pulse with flushed skin"}, {"id": "c", "text": "Fatigue"}, {"id": "d", "text": "Dizziness"}, {"id": "e", "text": "Pallor"}]'::jsonb, '["c", "d", "e"]', 'Symptomatic sinus bradycardia causes dizziness, pallor, and fatigue and is treated with atropine.', 'EKG', true, 53, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which findings are consistent with sinus tachycardia? (Select all that apply)', 'Which findings are consistent with sinus tachycardia? (Select all that apply)', '[{"id": "a", "text": "Normal P waves before each QRS"}, {"id": "b", "text": "Regular rhythm"}, {"id": "c", "text": "Sawtooth flutter waves"}, {"id": "d", "text": "Heart rate of 100-150 bpm"}, {"id": "e", "text": "Irregular rhythm with a wavy baseline"}]'::jsonb, '["a", "b", "d"]', 'Sinus tachycardia is regular at 100-150 bpm with normal P waves and a normal PR interval.', 'EKG', true, 54, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which findings are consistent with SVT? (Select all that apply)', 'Which findings are consistent with SVT? (Select all that apply)', '[{"id": "a", "text": "Wide, bizarre QRS complexes"}, {"id": "b", "text": "Irregular rhythm with no distinct P waves"}, {"id": "c", "text": "Rate above 150 bpm"}, {"id": "d", "text": "Regular rhythm with a narrow QRS"}, {"id": "e", "text": "P waves hidden in the preceding T wave"}]'::jsonb, '["c", "d", "e"]', 'SVT is a rapid, regular rhythm above 150 bpm with a narrow QRS and P waves that may be hidden in the T wave.', 'EKG', true, 55, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which interventions are appropriate for a stable client in SVT? (Select all that apply)', 'Which interventions are appropriate for a stable client in SVT? (Select all that apply)', '[{"id": "a", "text": "IV adenosine if vagal maneuvers fail"}, {"id": "b", "text": "Cold water or ice applied to the face"}, {"id": "c", "text": "Unsynchronized defibrillation"}, {"id": "d", "text": "A Valsalva maneuver"}, {"id": "e", "text": "IV atropine"}]'::jsonb, '["a", "b", "d"]', 'SVT is treated with vagal maneuvers first, then adenosine IV. Unstable clients are cardioverted.', 'EKG', true, 56, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which medications are used to treat sinus tachycardia? (Select all that apply)', 'Which medications are used to treat sinus tachycardia? (Select all that apply)', '[{"id": "a", "text": "Digoxin"}, {"id": "b", "text": "Atropine"}, {"id": "c", "text": "IV magnesium sulfate"}, {"id": "d", "text": "Metoprolol"}, {"id": "e", "text": "Diltiazem or verapamil"}]'::jsonb, '["a", "d", "e"]', 'Sinus tachycardia is treated with calcium channel blockers, beta-blockers such as metoprolol, or digoxin. Atropine raises the heart rate.', 'EKG', true, 57, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which findings are consistent with atrial flutter? (Select all that apply)', 'Which findings are consistent with atrial flutter? (Select all that apply)', '[{"id": "a", "text": "Sawtooth flutter waves"}, {"id": "b", "text": "Narrow QRS complexes"}, {"id": "c", "text": "A flat line with no electrical activity"}, {"id": "d", "text": "Atrial rate of 250-350 bpm"}, {"id": "e", "text": "Wide, bizarre QRS complexes"}]'::jsonb, '["a", "b", "d"]', 'Atrial flutter has sawtooth F waves, an atrial rate of 250-350 bpm, and narrow QRS complexes.', 'EKG', true, 58, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which findings are consistent with atrial fibrillation? (Select all that apply)', 'Which findings are consistent with atrial fibrillation? (Select all that apply)', '[{"id": "a", "text": "Irregular rhythm with a variable rate"}, {"id": "b", "text": "Sawtooth flutter waves"}, {"id": "c", "text": "Narrow QRS complexes"}, {"id": "d", "text": "A constant PR interval before every QRS"}, {"id": "e", "text": "No distinct P waves"}]'::jsonb, '["a", "c", "e"]', 'A-fib is irregular with a wavy baseline, no distinct P waves, and a narrow QRS.', 'EKG', true, 59, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which treatments are used for atrial fibrillation? (Select all that apply)', 'Which treatments are used for atrial fibrillation? (Select all that apply)', '[{"id": "a", "text": "Anticoagulants such as heparin then warfarin"}, {"id": "b", "text": "IV magnesium sulfate"}, {"id": "c", "text": "Rate control with a beta-blocker or diltiazem"}, {"id": "d", "text": "Rhythm control with amiodarone or cardioversion"}, {"id": "e", "text": "Atropine"}]'::jsonb, '["a", "c", "d"]', 'A-fib is treated with anticoagulants to prevent stroke, rate control, and rhythm control.', 'EKG', true, 60, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which findings are consistent with ventricular tachycardia? (Select all that apply)', 'Which findings are consistent with ventricular tachycardia? (Select all that apply)', '[{"id": "a", "text": "Sawtooth flutter waves"}, {"id": "b", "text": "No P waves"}, {"id": "c", "text": "Narrow QRS with hidden P waves"}, {"id": "d", "text": "Wide, bizarre QRS complexes"}, {"id": "e", "text": "Rate of 100-250 bpm"}]'::jsonb, '["b", "d", "e"]', 'V-Tach has a rate of 100-250 bpm with wide, bizarre QRS complexes and no P waves.', 'EKG', true, 61, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'A client in ventricular tachycardia has no pulse. Which actions does the nurse take? (Select all that apply)', 'A client in ventricular tachycardia has no pulse. Which actions does the nurse take? (Select all that apply)', '[{"id": "a", "text": "Start CPR"}, {"id": "b", "text": "Perform a vagal maneuver"}, {"id": "c", "text": "Perform synchronized cardioversion"}, {"id": "d", "text": "Call Code Blue"}, {"id": "e", "text": "Defibrillate with the SYNC button off"}]'::jsonb, '["a", "d", "e"]', 'Pulseless V-Tach is treated as cardiac arrest: Code Blue, CPR, defibrillation, then epinephrine and amiodarone.', 'EKG', true, 62, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which findings are consistent with ventricular fibrillation? (Select all that apply)', 'Which findings are consistent with ventricular fibrillation? (Select all that apply)', '[{"id": "a", "text": "A compensatory pause after each beat"}, {"id": "b", "text": "No identifiable QRS or P waves"}, {"id": "c", "text": "No effective pulse"}, {"id": "d", "text": "Chaotic electrical activity"}, {"id": "e", "text": "Pacing spikes before the QRS"}]'::jsonb, '["b", "c", "d"]', 'V-Fib is chaotic electrical activity with no QRS or P waves and no effective pulse. It is a shockable rhythm.', 'EKG', true, 63, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which findings are consistent with PVCs? (Select all that apply)', 'Which findings are consistent with PVCs? (Select all that apply)', '[{"id": "a", "text": "Sawtooth baseline"}, {"id": "b", "text": "A compensatory pause after the beat"}, {"id": "c", "text": "Pacing spike before each P wave"}, {"id": "d", "text": "No P wave before the beat"}, {"id": "e", "text": "Wide, bizarre QRS"}]'::jsonb, '["b", "d", "e"]', 'PVCs are wide, bizarre QRS complexes with no preceding P wave, followed by a compensatory pause.', 'EKG', true, 64, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which nursing actions are appropriate for a client with frequent PVCs? (Select all that apply)', 'Which nursing actions are appropriate for a client with frequent PVCs? (Select all that apply)', '[{"id": "a", "text": "Check electrolytes"}, {"id": "b", "text": "Give IV adenosine"}, {"id": "c", "text": "Start chest compressions"}, {"id": "d", "text": "Monitor closely"}, {"id": "e", "text": "Look for underlying causes such as ischemia"}]'::jsonb, '["a", "d", "e"]', 'Monitor closely and address underlying causes such as electrolyte imbalance or ischemia. Three or more in a row is V-Tach.', 'EKG', true, 65, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which findings are consistent with first-degree AV block? (Select all that apply)', 'Which findings are consistent with first-degree AV block? (Select all that apply)', '[{"id": "a", "text": "Every P wave conducts to the ventricles"}, {"id": "b", "text": "P waves independent of the QRS"}, {"id": "c", "text": "PR interval greater than 0.20 sec"}, {"id": "d", "text": "A QRS dropped after progressive PR lengthening"}, {"id": "e", "text": "A heart rate of 60-100 bpm"}]'::jsonb, '["a", "c", "e"]', 'First-degree block has a prolonged PR interval, but every P wave conducts and the rate is normal.', 'EKG', true, 66, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements are true about second-degree AV block type I (Wenckebach)? (Select all that apply)', 'Which statements are true about second-degree AV block type I (Wenckebach)? (Select all that apply)', '[{"id": "a", "text": "Increased vagal tone or medications can cause it"}, {"id": "b", "text": "A QRS complex is eventually dropped"}, {"id": "c", "text": "The PR interval lengthens progressively"}, {"id": "d", "text": "The PR interval stays constant"}, {"id": "e", "text": "P waves and QRS complexes are completely independent"}]'::jsonb, '["a", "b", "c"]', 'Wenckebach has a progressively lengthening PR interval until a QRS is dropped and can be caused by vagal tone or medications.', 'EKG', true, 67, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements are true about second-degree AV block type II (Mobitz II)? (Select all that apply)', 'Which statements are true about second-degree AV block type II (Mobitz II)? (Select all that apply)', '[{"id": "a", "text": "No treatment is needed"}, {"id": "b", "text": "Structural heart disease can cause it"}, {"id": "c", "text": "The PR interval is constant for conducted beats"}, {"id": "d", "text": "Some P waves are not conducted"}, {"id": "e", "text": "The PR interval lengthens until a beat is dropped"}]'::jsonb, '["b", "c", "d"]', 'Mobitz II has a constant PR interval with non-conducted P waves, is caused by structural heart disease, and needs an urgent pacemaker.', 'EKG', true, 68, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements are true about third-degree (complete) heart block? (Select all that apply)', 'Which statements are true about third-degree (complete) heart block? (Select all that apply)', '[{"id": "a", "text": "P waves and QRS complexes are independent"}, {"id": "b", "text": "The PR interval is constant"}, {"id": "c", "text": "The ventricular rate is 30-40 bpm"}, {"id": "d", "text": "An emergency pacemaker is required"}, {"id": "e", "text": "Every P wave conducts to the ventricles"}]'::jsonb, '["a", "c", "d"]', 'In complete heart block the atria and ventricles do not communicate. The rate is 30-40 bpm and an emergency pacemaker is required.', 'EKG', true, 69, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which findings are consistent with an artificial pacemaker rhythm? (Select all that apply)', 'Which findings are consistent with an artificial pacemaker rhythm? (Select all that apply)', '[{"id": "a", "text": "A regular rate set by the pacemaker"}, {"id": "b", "text": "A wavy baseline with no P waves"}, {"id": "c", "text": "A QRS that may be normal or widened"}, {"id": "d", "text": "Pacing spikes before P waves or QRS complexes"}, {"id": "e", "text": "Sawtooth flutter waves"}]'::jsonb, '["a", "c", "d"]', 'A paced rhythm has a regular rate, pacing spikes, and a normal or wide QRS depending on atrial versus ventricular pacing.', 'EKG', true, 70, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which actions are appropriate for asystole? (Select all that apply)', 'Which actions are appropriate for asystole? (Select all that apply)', '[{"id": "a", "text": "Perform synchronized cardioversion"}, {"id": "b", "text": "Start CPR immediately"}, {"id": "c", "text": "Give epinephrine"}, {"id": "d", "text": "Defibrillate immediately"}, {"id": "e", "text": "Confirm the rhythm in two leads"}]'::jsonb, '["b", "c", "e"]', 'Asystole is non-shockable: confirm in 2 leads, start CPR, give epinephrine, and treat reversible causes.', 'EKG', true, 71, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements are true about torsades de pointes? (Select all that apply)', 'Which statements are true about torsades de pointes? (Select all that apply)', '[{"id": "a", "text": "It is treated first with atropine"}, {"id": "b", "text": "It can degenerate into ventricular fibrillation"}, {"id": "c", "text": "It is caused by hypermagnesemia"}, {"id": "d", "text": "A prolonged QT interval precedes onset"}, {"id": "e", "text": "QRS complexes twist around the baseline"}]'::jsonb, '["b", "d", "e"]', 'Torsades has a twisting ''spindle'' QRS, follows a prolonged QT, can become V-Fib, and is treated with IV magnesium sulfate.', 'EKG', true, 72, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which EKG findings suggest cardiac tamponade? (Select all that apply)', 'Which EKG findings suggest cardiac tamponade? (Select all that apply)', '[{"id": "a", "text": "Sinus tachycardia"}, {"id": "b", "text": "Low-voltage QRS complexes"}, {"id": "c", "text": "Electrical alternans"}, {"id": "d", "text": "Sawtooth flutter waves"}, {"id": "e", "text": "Pacing spikes"}]'::jsonb, '["a", "b", "c"]', 'Tamponade shows electrical alternans, low-voltage QRS, and compensatory sinus tachycardia.', 'EKG', true, 73, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which rhythms are shockable in cardiac arrest? (Select all that apply)', 'Which rhythms are shockable in cardiac arrest? (Select all that apply)', '[{"id": "a", "text": "Pulseless electrical activity (PEA)"}, {"id": "b", "text": "Ventricular fibrillation"}, {"id": "c", "text": "First-degree AV block"}, {"id": "d", "text": "Asystole"}, {"id": "e", "text": "Pulseless ventricular tachycardia"}]'::jsonb, '["b", "e"]', 'V-Fib and pulseless V-Tach are shockable. Asystole and PEA are not.', 'EKG', true, 74, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which rhythms are non-shockable in cardiac arrest? (Select all that apply)', 'Which rhythms are non-shockable in cardiac arrest? (Select all that apply)', '[{"id": "a", "text": "Pulseless electrical activity (PEA)"}, {"id": "b", "text": "Pulseless torsades de pointes"}, {"id": "c", "text": "Ventricular fibrillation"}, {"id": "d", "text": "Pulseless ventricular tachycardia"}, {"id": "e", "text": "Asystole"}]'::jsonb, '["a", "e"]', 'Never shock asystole or PEA. They are treated with CPR and epinephrine.', 'EKG', true, 75, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements describe cardioversion? (Select all that apply)', 'Which statements describe cardioversion? (Select all that apply)', '[{"id": "a", "text": "The machine is set to SYNC ON"}, {"id": "b", "text": "A low-energy controlled shock is delivered"}, {"id": "c", "text": "The shock is delivered immediately regardless of the R wave"}, {"id": "d", "text": "The client is in cardiac arrest"}, {"id": "e", "text": "The client has a pulse"}]'::jsonb, '["a", "b", "e"]', 'Cardioversion is for a client with a pulse. It is a low-energy shock timed to the R wave with SYNC ON.', 'EKG', true, 76, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements describe defibrillation? (Select all that apply)', 'Which statements describe defibrillation? (Select all that apply)', '[{"id": "a", "text": "The client has no pulse"}, {"id": "b", "text": "CPR is performed before and after the shock"}, {"id": "c", "text": "The client is sedated first"}, {"id": "d", "text": "The SYNC button is on"}, {"id": "e", "text": "A high-energy shock is delivered"}]'::jsonb, '["a", "b", "e"]', 'Defibrillation is a high-energy, SYNC OFF shock for a pulseless client and is always preceded and followed by CPR.', 'EKG', true, 77, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which rhythms are treated with synchronized cardioversion when a pulse is present? (Select all that apply)', 'Which rhythms are treated with synchronized cardioversion when a pulse is present? (Select all that apply)', '[{"id": "a", "text": "Asystole"}, {"id": "b", "text": "Ventricular tachycardia with a pulse"}, {"id": "c", "text": "Supraventricular tachycardia"}, {"id": "d", "text": "Ventricular fibrillation"}, {"id": "e", "text": "Atrial flutter"}]'::jsonb, '["b", "c", "e"]', 'Cardioversion is used for SVT, A-fib, A-flutter, and V-Tach with a pulse. V-Fib is defibrillated and asystole is not shocked.', 'EKG', true, 78, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about ECG paper at standard speed are correct? (Select all that apply)', 'Which statements about ECG paper at standard speed are correct? (Select all that apply)', '[{"id": "a", "text": "The paper speed is 50 mm/sec"}, {"id": "b", "text": "Five large boxes equal 1 second"}, {"id": "c", "text": "One large box equals 0.20 sec"}, {"id": "d", "text": "One small box equals 0.04 sec"}, {"id": "e", "text": "One large box equals 0.04 sec"}]'::jsonb, '["b", "c", "d"]', 'At 25 mm/sec a small box is 0.04 sec, a large box is 0.20 sec, and 5 large boxes are 1 second.', 'EKG', true, 79, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which waveform measurements are within normal limits? (Select all that apply)', 'Which waveform measurements are within normal limits? (Select all that apply)', '[{"id": "a", "text": "PR interval of 0.16 sec"}, {"id": "b", "text": "QRS of 0.16 sec"}, {"id": "c", "text": "QRS of 0.08 sec"}, {"id": "d", "text": "QT interval of 0.40 sec"}, {"id": "e", "text": "PR interval of 0.30 sec"}]'::jsonb, '["a", "c", "d"]', 'Normal values are PR 0.12-0.20 sec, QRS below 0.12 sec, and QT 0.36-0.44 sec.', 'EKG', true, 80, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which waveforms are correctly matched with the cardiac event? (Select all that apply)', 'Which waveforms are correctly matched with the cardiac event? (Select all that apply)', '[{"id": "a", "text": "T wave: ventricular repolarization"}, {"id": "b", "text": "P wave: atrial depolarization"}, {"id": "c", "text": "PR segment: ventricular repolarization"}, {"id": "d", "text": "QRS complex: atrial repolarization"}, {"id": "e", "text": "QRS complex: ventricular depolarization"}]'::jsonb, '["a", "b", "e"]', 'The P wave is atrial depolarization, the QRS is ventricular depolarization, and the T wave is ventricular repolarization.', 'EKG', true, 81, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which methods can the nurse use to determine heart rate? (Select all that apply)', 'Which methods can the nurse use to determine heart rate? (Select all that apply)', '[{"id": "a", "text": "Multiply the P wave count in one large box by 60"}, {"id": "b", "text": "Multiply the QRS count in a 6-second strip by 10 in an irregular rhythm"}, {"id": "c", "text": "Match large boxes to 300, 150, 100, 75, 60, 50 for a regular rhythm"}, {"id": "d", "text": "Divide 150 by the number of small boxes in the PR interval"}, {"id": "e", "text": "Divide 300 by the large boxes between R waves in a regular rhythm"}]'::jsonb, '["b", "c", "e"]', 'Regular rhythms use 300 divided by large boxes or the 300-150-100-75-60-50 sequence. Irregular rhythms use the QRS count x 10.', 'EKG', true, 82, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which rhythms are irregular? (Select all that apply)', 'Which rhythms are irregular? (Select all that apply)', '[{"id": "a", "text": "Sinus bradycardia"}, {"id": "b", "text": "Normal sinus rhythm with PVCs"}, {"id": "c", "text": "Second-degree AV block type I"}, {"id": "d", "text": "First-degree AV block"}, {"id": "e", "text": "Atrial fibrillation"}]'::jsonb, '["b", "c", "e"]', 'A-fib is irregular, PVCs add occasional irregular beats, and Wenckebach drops beats. Sinus bradycardia and first-degree block are regular.', 'EKG', true, 83, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which rhythms typically have a narrow QRS complex? (Select all that apply)', 'Which rhythms typically have a narrow QRS complex? (Select all that apply)', '[{"id": "a", "text": "Ventricular tachycardia"}, {"id": "b", "text": "Atrial fibrillation"}, {"id": "c", "text": "Supraventricular tachycardia"}, {"id": "d", "text": "Atrial flutter"}, {"id": "e", "text": "Ventricular fibrillation"}]'::jsonb, '["b", "c", "d"]', 'Supraventricular rhythms have narrow QRS complexes. V-Tach is wide and bizarre and V-Fib is chaotic.', 'EKG', true, 84, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which rhythms lack distinct P waves? (Select all that apply)', 'Which rhythms lack distinct P waves? (Select all that apply)', '[{"id": "a", "text": "Sinus bradycardia"}, {"id": "b", "text": "Normal sinus rhythm"}, {"id": "c", "text": "Ventricular fibrillation"}, {"id": "d", "text": "Atrial fibrillation"}, {"id": "e", "text": "Ventricular tachycardia"}]'::jsonb, '["c", "d", "e"]', 'A-fib, V-Tach, and V-Fib have no distinct P waves. Normal sinus rhythm and sinus bradycardia have normal P waves.', 'EKG', true, 85, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which rhythms may require a pacemaker? (Select all that apply)', 'Which rhythms may require a pacemaker? (Select all that apply)', '[{"id": "a", "text": "Sinus tachycardia"}, {"id": "b", "text": "Third-degree AV block"}, {"id": "c", "text": "Second-degree AV block type I"}, {"id": "d", "text": "First-degree AV block"}, {"id": "e", "text": "Second-degree AV block type II"}]'::jsonb, '["b", "c", "e"]', 'Second-degree blocks and complete heart block need a pacemaker. First-degree block needs no treatment.', 'EKG', true, 86, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which rhythms need no treatment? (Select all that apply)', 'Which rhythms need no treatment? (Select all that apply)', '[{"id": "a", "text": "First-degree AV block"}, {"id": "b", "text": "Ventricular tachycardia"}, {"id": "c", "text": "Asymptomatic sinus bradycardia"}, {"id": "d", "text": "Normal sinus rhythm"}, {"id": "e", "text": "Torsades de pointes"}]'::jsonb, '["a", "c", "d"]', 'Normal sinus rhythm, first-degree block, and asymptomatic sinus bradycardia are monitored. V-Tach and torsades need treatment.', 'EKG', true, 87, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which rhythms carry a risk of stroke from clot formation? (Select all that apply)', 'Which rhythms carry a risk of stroke from clot formation? (Select all that apply)', '[{"id": "a", "text": "Normal sinus rhythm"}, {"id": "b", "text": "Atrial flutter"}, {"id": "c", "text": "Atrial fibrillation"}, {"id": "d", "text": "Sinus bradycardia"}, {"id": "e", "text": "First-degree AV block"}]'::jsonb, '["b", "c"]', 'Atrial flutter and A-fib carry a risk of blood clots and stroke, so anticoagulants are used.', 'EKG', true, 88, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'A client''s monitor shows ventricular fibrillation. Which priority actions does the nurse take? (Select all that apply)', 'A client''s monitor shows ventricular fibrillation. Which priority actions does the nurse take? (Select all that apply)', '[{"id": "a", "text": "Check for a pulse"}, {"id": "b", "text": "Wait 10 minutes to see whether the rhythm resolves"}, {"id": "c", "text": "Perform a vagal maneuver"}, {"id": "d", "text": "Call a code"}, {"id": "e", "text": "Start CPR until the defibrillator is ready"}]'::jsonb, '["a", "d", "e"]', 'Always check the pulse first. V-Fib is an emergency treated with a code, CPR, and defibrillation.', 'EKG', true, 89, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which medication-rhythm pairings are correct? (Select all that apply)', 'Which medication-rhythm pairings are correct? (Select all that apply)', '[{"id": "a", "text": "Atropine: symptomatic sinus bradycardia"}, {"id": "b", "text": "Atropine: ventricular fibrillation"}, {"id": "c", "text": "Adenosine: pulseless ventricular tachycardia"}, {"id": "d", "text": "Magnesium sulfate: torsades de pointes"}, {"id": "e", "text": "Adenosine: SVT after vagal maneuvers fail"}]'::jsonb, '["a", "d", "e"]', 'Atropine treats symptomatic sinus bradycardia, adenosine treats SVT, and magnesium sulfate treats torsades de pointes.', 'EKG', true, 90, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which rhythm-rate pairings are correct? (Select all that apply)', 'Which rhythm-rate pairings are correct? (Select all that apply)', '[{"id": "a", "text": "Third-degree block: 30-40 bpm"}, {"id": "b", "text": "SVT: below 60 bpm"}, {"id": "c", "text": "Sinus tachycardia: 100-150 bpm"}, {"id": "d", "text": "Torsades de pointes: below 40 bpm"}, {"id": "e", "text": "Normal sinus rhythm: 60-100 bpm"}]'::jsonb, '["a", "c", "e"]', 'Normal sinus rhythm is 60-100 bpm, sinus tachycardia 100-150 bpm, and complete heart block 30-40 bpm. SVT and torsades are fast.', 'EKG', true, 91, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'A client is taking digoxin. Which findings should the nurse report as signs of toxicity? (Select all that apply)', 'A client is taking digoxin. Which findings should the nurse report as signs of toxicity? (Select all that apply)', '[{"id": "a", "text": "Improved energy"}, {"id": "b", "text": "Increased appetite"}, {"id": "c", "text": "A slow, fast, or irregular pulse"}, {"id": "d", "text": "Yellow or green vision with halos"}, {"id": "e", "text": "Nausea and vomiting"}]'::jsonb, '["c", "d", "e"]', 'Digoxin toxicity causes nausea, vomiting, loss of appetite, confusion, visual changes, and pulse abnormalities.', 'EKG', true, 92, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which factors are associated with torsades de pointes? (Select all that apply)', 'Which factors are associated with torsades de pointes? (Select all that apply)', '[{"id": "a", "text": "A shortened PR interval"}, {"id": "b", "text": "Hypermagnesemia"}, {"id": "c", "text": "Hypomagnesemia"}, {"id": "d", "text": "A prolonged QT interval"}, {"id": "e", "text": "QT-prolonging medications"}]'::jsonb, '["c", "d", "e"]', 'Torsades is associated with hypomagnesemia and QT-prolonging drugs, and a prolonged QT precedes onset.', 'EKG', true, 93, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which actions are appropriate when the monitor shows a flat line? (Select all that apply)', 'Which actions are appropriate when the monitor shows a flat line? (Select all that apply)', '[{"id": "a", "text": "Charge the defibrillator and shock"}, {"id": "b", "text": "Confirm the rhythm in two leads"}, {"id": "c", "text": "Check the client''s pulse"}, {"id": "d", "text": "Turn on the SYNC button"}, {"id": "e", "text": "Begin CPR if the client is pulseless"}]'::jsonb, '["b", "c", "e"]', 'Check the pulse and confirm asystole in 2 leads. Asystole is never shocked, so CPR and epinephrine are given.', 'EKG', true, 94, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about heart block are true? (Select all that apply)', 'Which statements about heart block are true? (Select all that apply)', '[{"id": "a", "text": "There are four degrees of severity"}, {"id": "b", "text": "The SA and AV nodes fail to communicate properly"}, {"id": "c", "text": "Every degree requires an emergency pacemaker"}, {"id": "d", "text": "In first-degree block every P wave conducts, but slowly"}, {"id": "e", "text": "The heart rate is always above 100 bpm"}]'::jsonb, '["a", "b", "d"]', 'Heart block is a communication failure between the SA and AV nodes with 4 degrees of severity. First-degree block needs no treatment.', 'EKG', true, 95, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about synchronized cardioversion are correct? (Select all that apply)', 'Which statements about synchronized cardioversion are correct? (Select all that apply)', '[{"id": "a", "text": "This avoids the vulnerable T wave"}, {"id": "b", "text": "The shock is delivered on the R wave"}, {"id": "c", "text": "The shock is delivered immediately without waiting for the R wave"}, {"id": "d", "text": "The client may be sedated first"}, {"id": "e", "text": "It is used for ventricular fibrillation"}]'::jsonb, '["a", "b", "d"]', 'With SYNC ON the shock fires on the R wave, avoiding the T wave. The client may be sedated first.', 'EKG', true, 96, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements describe depolarization? (Select all that apply)', 'Which statements describe depolarization? (Select all that apply)', '[{"id": "a", "text": "A wave moving toward a lead causes a downward deflection"}, {"id": "b", "text": "The cell resets from positive to negative"}, {"id": "c", "text": "Sodium enters the cell"}, {"id": "d", "text": "A wave moving toward a lead causes an upward deflection"}, {"id": "e", "text": "The charge goes from negative to positive"}]'::jsonb, '["c", "d", "e"]', 'In depolarization Na+ enters the cell and the charge goes negative to positive. Toward a lead is a bump up and away is a dip down.', 'EKG', true, 97, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements describe repolarization? (Select all that apply)', 'Which statements describe repolarization? (Select all that apply)', '[{"id": "a", "text": "The cell resets"}, {"id": "b", "text": "A wave moving away from a lead causes an upward deflection"}, {"id": "c", "text": "Sodium enters the cell"}, {"id": "d", "text": "The charge goes from positive to negative"}, {"id": "e", "text": "A wave moving toward a lead causes an upward deflection"}]'::jsonb, '["a", "b", "d"]', 'In repolarization the cell resets from positive to negative. Toward a lead is a dip down and away is a bump up.', 'EKG', true, 98, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which findings are consistent with atrial fibrillation on assessment? (Select all that apply)', 'Which findings are consistent with atrial fibrillation on assessment? (Select all that apply)', '[{"id": "a", "text": "An irregular pulse"}, {"id": "b", "text": "A regular rhythm with sawtooth waves"}, {"id": "c", "text": "An increased risk of blood clots and stroke"}, {"id": "d", "text": "A wavy, chaotic baseline on the strip"}, {"id": "e", "text": "A constant PR interval"}]'::jsonb, '["a", "c", "d"]', 'A-fib is irregular with a chaotic baseline and a risk of clots and stroke.', 'EKG', true, 99, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about the QRS complex are correct? (Select all that apply)', 'Which statements about the QRS complex are correct? (Select all that apply)', '[{"id": "a", "text": "It represents ventricular depolarization"}, {"id": "b", "text": "A normal QRS is 0.20 sec or longer"}, {"id": "c", "text": "It represents atrial depolarization"}, {"id": "d", "text": "A QRS wider than 3 small boxes is abnormal"}, {"id": "e", "text": "A normal QRS is narrow, less than 0.12 sec"}]'::jsonb, '["a", "d", "e"]', 'The QRS is ventricular depolarization. Normal is narrow (below 0.12 sec) and more than 3 small boxes is wide and abnormal.', 'EKG', true, 100, 1, true);
